def get_voice_by_id(voice_id: str):
    for voice in VOICE_PROFILES:
        if voice["id"] == voice_id:
            return voice
    return None


def get_voices_by_style(style: str):
    return [v for v in VOICE_PROFILES if v["style"] == style]


def get_voices_by_gender(gender: str):
    return [v for v in VOICE_PROFILES if v["gender"] == gender]


def get_voices_by_accent(accent: str):
    return [v for v in VOICE_PROFILES if accent.lower() in v["accent"].lower()]
